function hostMatches(hostname: string, brandHost: string): boolean {
  if (brandHost === 'aiplatform.googleapis.com' && hostname.endsWith('-aiplatform.googleapis.com')) return true;
  if (brandHost === 'ai-gateway.vercel.sh') return hostname === brandHost;
  return hostname === brandHost || hostname.endsWith(`.${brandHost}`);
}

/** Resolve one deterministic brand from stable provider id, then persisted upstream routing. */
export function resolveProviderLogoKind(
  providerId: string,
  routing?: ProviderLogoRouting,
): ProviderLogoKind | null {
  const byId = PROVIDER_LOGO_KIND_BY_ID[providerId];
  if (byId) return byId;

  let routedKind: ProviderLogoKind | null = null;
  for (const descriptor of Object.values(routing ?? {})) {
    if (!descriptor) continue;
    try {
      const hostname = new URL(descriptor.upstream.replace(/\{[A-Za-z][A-Za-z0-9_]*\}/g, 'account')).hostname.toLowerCase();
      const match = PROVIDER_LOGO_KIND_BY_HOST.find(([host]) => hostMatches(hostname, host));
      if (!match) continue;
      // A provider routing different agents to different brands has no single brand mark.
      if (routedKind && routedKind !== match[1]) return null;
      routedKind = match[1];
    } catch {
      // Provider validation owns malformed URLs; presentation safely falls back to a monogram.
    }
  }
  return routedKind;
}

/** Whether the shared catalog contains an official monochrome mark for this provider. */
export function hasProviderLogo(providerId: string, routing?: ProviderLogoRouting): boolean {
  return resolveProviderLogoKind(providerId, routing) !== null;
}
